<!-- Página de manutenção, tarefas, auditoria e diagnóstico. -->
<script setup lang="ts">import{computed,onMounted,ref}from"vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import AuditLogPanel from"@/components/maintenance/AuditLogPanel.vue";import IncompleteRecordsPanel from"@/components/maintenance/IncompleteRecordsPanel.vue";import SyncJobPanel from"@/components/maintenance/SyncJobPanel.vue";import{detectIncompleteSources,detectIncompleteTitles,detectStuckJobs}from"@/domain/maintenance/diagnostics";import{auditLogRepository,externalSourceRepository,syncJobRepository}from"@/domain/providers/repository";import{titleRepository}from"@/domain/repositories";import type{AuditLogRecord,ExternalSourceRecord,SyncJobRecord}from"@/domain/providers/records";import type{TitleRecord}from"@/types/records";const jobs=ref<SyncJobRecord[]>([]),logs=ref<AuditLogRecord[]>([]),sources=ref<ExternalSourceRecord[]>([]),titles=ref<TitleRecord[]>([]),loading=ref(true),error=ref("");const issues=computed(()=>[...detectStuckJobs(jobs.value),...detectIncompleteSources(sources.value),...detectIncompleteTitles(titles.value)]);async function load(){loading.value=true;try{const[j,l,s,t]=await Promise.all([syncJobRepository.list({page:1,perPage:500,sort:"-iniciado_em"}),auditLogRepository.list({page:1,perPage:500,sort:"-created"}),externalSourceRepository.list({page:1,perPage:500,sort:"provider"}),titleRepository.list({page:1,perPage:500,filter:"apagado = false",sort:"titulo"})]);jobs.value=j.items;logs.value=l.items;sources.value=s.items;titles.value=t.items}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}onMounted(load);</script><template><BasePageHeader eyebrow="Operações técnicas" title="Manutenção" description="Tarefas de sincronização, auditoria e diagnóstico de dados."><template #actions><button class="button button-secondary" type="button" :disabled="loading" @click="load">Atualizar diagnóstico</button></template></BasePageHeader><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><p v-if="loading" class="page-loading">A carregar dados de manutenção…</p><template v-else><IncompleteRecordsPanel :issues="issues"/><SyncJobPanel :jobs="jobs"/><AuditLogPanel :items="logs"/></template></template>
